/** Record a death — POST /api/v1/patients/{patient_id}/death (who may call: holders of death.record). */
export function recordDeath(patient_id: number, body: DeathIn): Promise<DeathViewOut> {
  return api<DeathViewOut>("POST", `/patients/${patient_id}/death`, body, { idempotent: true });
}

/** A death record with its certificate — GET /api/v1/deaths/{death_id} (who may call: holders of death.record or death.body.release or death.register.view or death.autopsy.authorize). */
export function getDeath(death_id: number): Promise<DeathViewOut> {
  return api<DeathViewOut>("GET", `/deaths/${death_id}`, undefined);
}

/** Write the cause-of-death certificate (draft) — PUT /api/v1/deaths/{death_id} (who may call: holders of death.record). */
export function saveDeath(death_id: number, body: DeathDraftIn): Promise<DeathViewOut> {
  return api<DeathViewOut>("PUT", `/deaths/${death_id}`, body);
}

/** Certify the cause of death (final) — POST /api/v1/deaths/{death_id}/certify (who may call: holders of death.record). */
export function certifyDeath(death_id: number, body: CertifyIn): Promise<DeathViewOut> {
  return api<DeathViewOut>("POST", `/deaths/${death_id}/certify`, body);
}

/** Append a correction to a certified death record — POST /api/v1/deaths/{death_id}/corrections (who may call: holders of death.record). */
export function correctDeath(death_id: number, body: DeathCorrectionIn): Promise<DeathViewOut> {
  return api<DeathViewOut>("POST", `/deaths/${death_id}/corrections`, body, { idempotent: true });
}

/** Printable death certificate, or the order for a clinical autopsy — GET /api/v1/deaths/{death_id}/print-payload (who may call: holders of death.record or death.body.release or death.register.view or death.autopsy.authorize). */
export function deathPrint(death_id: number, query?: { document?: "certificate" | "autopsy_order" }): Promise<PrintOut_DeathPrintFieldsOut_> {
  return api<PrintOut_DeathPrintFieldsOut_>("GET", withQuery(`/deaths/${death_id}/print-payload`, query), undefined);
}

/** The death certificate or the autopsy order as a PDF — GET /api/v1/deaths/{death_id}/pdf (who may call: holders of death.record or death.body.release or death.register.view or death.autopsy.authorize). */
export function deathPdf(death_id: number, query?: { document?: "certificate" | "autopsy_order" }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/deaths/${death_id}/pdf`, query), undefined);
}

/** Ask for a clinical autopsy — POST /api/v1/deaths/{death_id}/autopsy (who may call: holders of death.record). */
export function requestAutopsy(death_id: number, body: AutopsyRequestIn): Promise<DeathViewOut> {
  return api<DeathViewOut>("POST", `/deaths/${death_id}/autopsy`, body, { idempotent: true });
}

/** Record the autopsy report — POST /api/v1/deaths/{death_id}/autopsy/report (who may call: holders of death.record or death.autopsy.authorize). */
export function reportAutopsy(death_id: number, body: AutopsyReportIn): Promise<DeathViewOut> {
  return api<DeathViewOut>("POST", `/deaths/${death_id}/autopsy/report`, body);
}

/** Cancel the autopsy request — POST /api/v1/deaths/{death_id}/autopsy/cancel (who may call: holders of death.record or death.autopsy.authorize). */
export function cancelAutopsy(death_id: number, body: AutopsyCancelIn): Promise<DeathViewOut> {
  return api<DeathViewOut>("POST", `/deaths/${death_id}/autopsy/cancel`, body, { idempotent: true });
}

/** The death register — GET /api/v1/deaths (who may call: holders of death.register.view or death.record or death.body.release). */
export function deathRegister(query?: { date_from?: string | null; date_to?: string | null; setting?: "Inpatient" | "Emergency" | "Outpatient" | "BroughtDead" | null; status?: "Draft" | "Certified" | null; medico_legal?: boolean | null; body_released?: boolean | null; patient_id?: number | null; limit?: number }): Promise<DeathRegisterRowOut[]> {
  return api<DeathRegisterRowOut[]>("GET", withQuery(`/deaths`, query), undefined);
}

/** ICD picker: search codes by code or words — GET /api/v1/icd/codes (who may call: any logged-in user). */
export function searchIcdCodes(query: { q: string; system?: "ICD-11" | "ICD-10" | null; limit?: number }): Promise<IcdSearchOut> {
  return api<IcdSearchOut>("GET", withQuery(`/icd/codes`, query), undefined);
}

/** ICD picker: browse chapters, blocks, categories — GET /api/v1/icd/browse (who may call: any logged-in user). */
export function browse(query?: { parent?: string | null; system?: "ICD-11" | "ICD-10" | null }): Promise<IcdBrowseOut> {
  return api<IcdBrowseOut>("GET", withQuery(`/icd/browse`, query), undefined);
}

/** One ICD code with its place in the tree — GET /api/v1/icd/codes/{code} (who may call: any logged-in user). */
export function detail(code: string, query?: { system?: "ICD-11" | "ICD-10" | null }): Promise<IcdDetailOut> {
  return api<IcdDetailOut>("GET", withQuery(`/icd/codes/${code}`, query), undefined);
}

/** The ICD code lists loaded — GET /api/v1/icd/releases (who may call: any logged-in user). */
export function releases(): Promise<IcdReleasesOut> {
  return api<IcdReleasesOut>("GET", `/icd/releases`, undefined);
}

/** Upload a patient document (PDF/JPEG/PNG) — POST /api/v1/patients/{patient_id}/documents (who may call: holders of patient.document.upload). */
export function uploadDocumentPatientsDocuments(patient_id: number, body: FormData): Promise<PatientDocumentUploadOut> {
  return api<PatientDocumentUploadOut>("POST", `/patients/${patient_id}/documents`, body, { idempotent: true });
}
